$(function () {
  let image = &quot;%2fPCUP%2fReligion-PNG%2fNorgorber.png&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;#symbole1&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td id=&quot;symbole1&quot; style=&quot;text-align:center;&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux aux fid&#232;les de la divinit&#233; indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Norgorber (technique).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/%2fPCUP%2fReligion-PNG%2fNorgorber.png&quot; style=&quot;max-height:70px; max-width:70px&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br/&gt;commune chez&lt;br/&gt;les fid&#232;les&lt;br/&gt;de &lt;a class=&quot;pagelink&quot; href=&quot;Norgorber-(Technique).html&quot; title=&quot;Norgorber&quot;&gt;Norgorber&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Gomme empoisonn&#233;e&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Gods/Dieux de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Necromancie.html&quot; title=&quot;N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt; faible ; &lt;b&gt;NLS&lt;/b&gt; 5 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;aucun&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 1 250 po ; &lt;b&gt;Poids&lt;/b&gt; —
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
La &lt;i&gt;gomme empoisonn&#233;e&lt;/i&gt; est souvent utilis&#233;e par les agents de &lt;a class=&quot;pagelink&quot; href=&quot;Norgorber-(Technique).html&quot; title=&quot;Norgorber&quot;&gt;Norgorber&lt;/a&gt;, en particulier les alchimistes et empoisonneurs qui v&#233;n&#232;rent le dieu insidieux sous le nom de Noirs Doigts. M&#226;cher un morceau de &lt;i&gt;gomme empoisonn&#233;e&lt;/i&gt; - qui ne ressemble &#224; rien d&#39;autre qu&#39;&#224; un morceau de s&#232;ve congel&#233;e - est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; qui provoque des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaques d&#39;opportunit&#233;&lt;/a&gt;, bien que l&#39;utilisateur puisse continuer &#224; m&#226;cher la gomme par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; pendant plusieurs rounds cons&#233;cutifs. Cette action remplit la bouche de l&#39;utilisateur de trois doses de &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Venindaraign&#233;edetailleM&quot; title=&quot;Les poisons  &quot;&gt;venin d&#39;araign&#233;e de taille M&lt;/a&gt;. Ce poison dure jusqu&#39;&#224; 5 minutes avant de perdre sa puissance. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pendant qu&#39;il m&#226;che une &lt;i&gt;gomme empoisonn&#233;e&lt;/i&gt;, l&#39;utilisateur peut appliquer le poison &#224; l&#39;arme qu&#39;il manie. Si l&#39;utilisateur n&#39;a pas la capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#UTILISATIONDUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;utilisation du poison&lt;/a&gt;, il a 5% de chances de s&#39;exposer au poison en m&#226;chant la gomme ou en appliquant le poison &#224; une arme, et s&#39;il obtient un 1 naturel sur un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d&#39;attaque&lt;/a&gt; avec une arme empoisonn&#233;e, il s&#39;expose &#233;galement au poison.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d&#39;objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Empoisonnement.html&quot; title=&quot;Empoisonnement&quot;&gt;empoisonnement&lt;/a&gt;&lt;/i&gt;, le cr&#233;ateur doit avoir la capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#UTILISATIONDUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;utilisation du poison&lt;/a&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 1 000 po
&lt;/div&gt;
